set role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000103","aal":"aal1"}',false);
select set_config('test.opportunity',public.save_opportunity(null,jsonb_build_object('name','PRIVATE scholarship fixture','provider','Test provider','destination','Test destination','studyLevel','Master''s','field','Engineering','requirements','Test requirements for applicant','staffNotes','INTERNAL research never in proposal','deadline',(current_date+30)::text,'sourceUrl','https://example.invalid/provider','providerFee','','providerCurrency','USD','image','/images/study-1.jpg','active',true))::text,false);
select set_config('test.package',public.save_service_package(null,'Test ISG package','Test-only scope',200000,true,true)::text,false);
select set_config('test.promotion',public.save_study_promotion(null,'{"title":"Broad study area","destination":"Test destination","studyLevel":"Masters","field":"Engineering","fundingType":"Partial or full funding","eligibility":"Individual assessment required","image":"/images/study-1.jpg","published":true}')::text,false);
select set_config('test.app1',public.propose_application('00000000-0000-4000-8000-000000000201',current_setting('test.opportunity')::uuid)::text,false);
select set_config('test.app2',public.propose_application('00000000-0000-4000-8000-000000000201',current_setting('test.opportunity')::uuid)::text,false);
do $$begin perform public.update_study_application(current_setting('test.app1')::uuid,'Applying','Pending',null,'','Begin application','Prepare',null);raise exception 'Unapproved submission';exception when raise_exception then if sqlerrm<>'Applicant approval required' then raise;end if;end $$;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000201","aal":"aal1"}',false);
select public.test_assert((select count(*)=2 from public.study_applications),'multiple independent applications');
select public.test_assert((select not proposal::text like '%INTERNAL%' from public.study_applications limit 1),'internal notes excluded from disclosed snapshot');
do $$begin perform public.admin_opportunities();raise exception 'Applicant read shortlist';exception when raise_exception then if sqlerrm<>'Access denied' then raise;end if;end $$;
select public.approve_application(current_setting('test.app1')::uuid,true);
select public.approve_application(current_setting('test.app2')::uuid,true);
select set_config('test.quote_version',(select updated_at::text from public.service_packages where id=current_setting('test.package')::uuid),false);
select public.test_assert((select price_tzs=200000 and description='Test-only scope' from public.service_packages where id=current_setting('test.package')::uuid),'applicant displayed original price and scope');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000103","aal":"aal1"}',false);
select public.save_service_package(current_setting('test.package')::uuid,'Updated ISG package','Revised test-only scope',300000,true,true);
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000201","aal":"aal1"}',false);
do $$begin perform public.accept_service_package(current_setting('test.package')::uuid,current_setting('test.quote_version')::timestamptz);raise exception 'Accepted stale quote';exception when raise_exception then if sqlerrm<>'Package quote changed; review the current price and scope' then raise;end if;end $$;
select public.test_assert((select count(*)=0 from public.service_orders),'stale quote creates no order and allocates no consultation credit');
select set_config('test.quote_version',(select updated_at::text from public.service_packages where id=current_setting('test.package')::uuid),false);
select public.accept_service_package(current_setting('test.package')::uuid,current_setting('test.quote_version')::timestamptz);
select public.test_assert((select package_name='Updated ISG package' and package_description='Revised test-only scope' and gross_tzs=300000 and consultation_credit_tzs=50000 and remaining_tzs=250000 from public.service_orders),'fresh quote snapshots agreed price and scope with consultation credited once');
do $$begin perform public.accept_service_package(current_setting('test.package')::uuid,current_setting('test.quote_version')::timestamptz);raise exception 'Repeated fee credit';exception when raise_exception then if sqlerrm<>'Consultation credit already allocated' then raise;end if;end $$;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000103","aal":"aal1"}',false);
select public.save_service_package(current_setting('test.package')::uuid,'Later ISG package','Later scope',400000,true,true);
select public.test_assert((select package_name='Updated ISG package' and package_description='Revised test-only scope' and gross_tzs=300000 from public.service_orders),'accepted quote remains unchanged after later package edits');
do $$begin perform public.update_study_application(current_setting('test.app1')::uuid,'Applying','Pending',null,'','Begin application','Prepare',null);raise exception 'Unapproved required documents';exception when raise_exception then if sqlerrm<>'Required documents need approval' then raise;end if;end $$;
-- An authorized advisor can waive a request with a recorded purpose in this disposable fixture.
select public.set_document_request('00000000-0000-4000-8000-000000000201',category,label,false,'Waived for test-only programme') from public.document_requests where user_id='00000000-0000-4000-8000-000000000201';
select public.update_study_application(current_setting('test.app1')::uuid,'Applying','Pending',null,'','Application prepared','Submit',current_date);
select public.update_study_application(current_setting('test.app1')::uuid,'Waiting for decision','Pending',null,'','Submitted to provider','Await decision',null);
do $$begin perform public.update_study_application(current_setting('test.app1')::uuid,'Accepted','Pending',null,'','False accepted outcome','',null);raise exception 'ISG invented acceptance';exception when raise_exception then if sqlerrm<>'Official decision required' then raise;end if;end $$;
select public.update_study_application(current_setting('test.app1')::uuid,'Rejected','Rejected',current_date,'Provider rejection letter reviewed in disposable test','Provider declined this application','Review another route',null);
select public.test_assert((select status='Starting' from public.study_applications where id=current_setting('test.app2')::uuid),'rejection leaves another application unchanged');
select public.update_study_application(current_setting('test.app2')::uuid,'Applying','Pending',null,'','Preparing second application','Submit',null);
select public.update_study_application(current_setting('test.app2')::uuid,'Accepted','Accepted',current_date,'Provider acceptance letter reviewed in disposable test','Official acceptance recorded','Applicant to choose place',null);
do $$begin perform public.update_study_application(current_setting('test.app2')::uuid,'Completed','Accepted',current_date,'Evidence','Staff forced commitment','',null);raise exception 'Staff forced commitment';exception when raise_exception then if sqlerrm<>'Invalid workflow transition' then raise;end if;end $$;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000201","aal":"aal1"}',false);
select public.commit_study_place(current_setting('test.app2')::uuid,false);
select public.test_assert((select status='Completed' from public.study_applications where id=current_setting('test.app2')::uuid),'applicant commits accepted place');
select public.test_assert((select status='Rejected' from public.study_applications where id=current_setting('test.app1')::uuid),'rejection history remains independent');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000202","aal":"aal1"}',false);
select public.test_assert((select count(*)=0 from public.study_applications),'applications isolated from other applicants');
select public.test_assert((select count(*)=0 from public.study_application_history),'application histories isolated');
reset role;
set role anon;
select public.test_assert((select count(*)=1 from public.study_promotions),'explicitly authored broad promotions public');
select public.test_assert((select count(*)=1 from public.service_packages),'approved ISG prices public');
do $$begin perform public.admin_opportunities();raise exception 'Anonymous shortlist RPC';exception when insufficient_privilege then null;end $$;
do $$begin perform 1 from private.opportunities;raise exception 'Anonymous private catalogue';exception when insufficient_privilege then null;end $$;
reset role;
select 'INDEPENDENT APPLICATIONS, PRIVATE CATALOGUE AND CREDIT PASSED' as result;
